select jsonb_build_object(
 'transactionReadOnly',current_setting('transaction_read_only'),
 'pgGraphqlInstalled',coalesce((select jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname)) from pg_extension e join pg_namespace n on n.oid=e.extnamespace where e.extname='pg_graphql'),'[]'::jsonb),
 'pgGraphqlAvailable',coalesce((select jsonb_agg(jsonb_build_object('name',name,'defaultVersion',default_version,'installedVersion',installed_version)) from pg_available_extensions where name='pg_graphql'),'[]'::jsonb),
 'graphqlSchemas',coalesce((select jsonb_agg(jsonb_build_object('name',n.nspname,'owner',pg_get_userbyid(n.nspowner),'rolePrivileges',(select jsonb_agg(jsonb_build_object('role',r.role,'usage',has_schema_privilege(r.role,n.oid,'USAGE'),'create',has_schema_privilege(r.role,n.oid,'CREATE'))) from (values('anon'),('authenticated'),('service_role'))r(role)))) from pg_namespace n where n.nspname in ('graphql','graphql_public')),'[]'::jsonb),
 'graphqlFunctions',coalesce((select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'securityDefiner',p.prosecdef,'settings',p.proconfig,'owner',pg_get_userbyid(p.proowner),'definition',pg_get_functiondef(p.oid),'execute',(select jsonb_agg(jsonb_build_object('role',r.role,'allowed',has_function_privilege(r.role,p.oid,'EXECUTE'))) from (values('anon'),('authenticated'),('service_role'))r(role)))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('graphql','graphql_public') and p.proname in ('graphql','resolve')),'[]'::jsonb),
 'graphqlRelations',coalesce((select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('graphql','graphql_public') and c.relkind in ('r','p','v','m','f')),'[]'::jsonb),
 'profilePolicy',coalesce((select jsonb_agg(jsonb_build_object('name',policyname,'command',cmd,'roles',roles,'using',qual,'check',with_check)) from pg_policies where schemaname='public' and tablename='profiles'),'[]'::jsonb),
 'profileColumnGrants',coalesce((select jsonb_agg(jsonb_build_object('column',a.attname,'select',has_column_privilege('authenticated',c.oid,a.attnum,'SELECT'),'update',has_column_privilege('authenticated',c.oid,a.attnum,'UPDATE'))) from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid where n.nspname='public' and c.relname='profiles' and a.attnum>0 and not a.attisdropped),'[]'::jsonb)
) as inspection;
